      "chunk_id": "text_8",
      "quote": "Subgroup analyses were performed by intervention methods (acupuncture vs acupuncture combine with moxibustion), different methods of medicine (western medicine vs Chinese and western medicine), published year (before 2005 vs after 2005), sample sizes ( ≥ 90 vs < 90).",
      "reason": "The manuscript specifies the groups used for synthesis (subgroup analyses)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not provide rationales for the notable restrictions on study eligibility (e.g., exclusion of gray literature or specific acupuncture types)."
    }
